-- Fonction de contrôle : un sujet est verrouillé pour p_user si un verrou actif
-- existe, qu'il n'en est pas l'auteur, et qu'aucun grant actif ne le concerne.
create or replace function private.is_locked_for(
  p_organization_id uuid,
  p_subject_type text,
  p_subject_id uuid,
  p_user_id uuid
)
returns boolean
language sql
stable
security definer
set search_path = public, private, pg_temp
as $$
  select exists (
    select 1
    from public.resource_lock rl
    where rl.organization_id = p_organization_id
      and rl.subject_type = p_subject_type
      and rl.subject_id = p_subject_id
      and rl.lock_state = 'active'
      and rl.locked_by <> p_user_id
      and not exists (
        select 1 from public.access_grant ag
        where ag.organization_id = p_organization_id
          and ag.subject_type = p_subject_type
          and ag.subject_id = p_subject_id
          and ag.grantee_user_id = p_user_id
          and ag.status = 'active'
          and ag.valid_from <= now()
          and (ag.valid_to is null or ag.valid_to > now())
      )
  );
$$;

revoke all on function private.is_locked_for(uuid, text, uuid, uuid) from public, anon;
grant execute on function private.is_locked_for(uuid, text, uuid, uuid) to authenticated;

