create or replace function public.is_super_admin_caller()
returns boolean language sql stable security definer set search_path = public as $$
  select exists (select 1 from public.profiles p where p.id = auth.uid() and p.is_super_admin = true);
$$;

create or replace function public.super_admin_ai_usage()
returns jsonb language plpgsql stable security definer set search_path = public as $$
declare
  result jsonb;
begin
  if not public.is_super_admin_caller() then
    raise exception 'forbidden';
  end if;

  with base as (select * from public.ai_usage_events),
  period as (
    select p.label, p.since from (values
      ('day',   now() - interval '1 day'),
      ('week',  now() - interval '7 days'),
      ('month', now() - interval '30 days'),
      ('year',  now() - interval '365 days'),
      ('all',   timestamptz '1970-01-01')
    ) as p(label, since)
  ),
  totals as (
    select period.label,
      count(base.id) as calls,
      coalesce(sum(base.total_tokens),0) as tokens,
      coalesce(sum(base.estimated_cost_usd),0) as cost
    from period left join base on base.created_at >= period.since
    group by period.label
  ),
  agg_fn as (
    select fn, count(*) calls, coalesce(sum(total_tokens),0) tokens, coalesce(sum(estimated_cost_usd),0) cost
    from base where created_at >= now() - interval '30 days' group by fn order by cost desc
  ),
  agg_model as (
    select model, count(*) calls, coalesce(sum(total_tokens),0) tokens, coalesce(sum(estimated_cost_usd),0) cost
    from base where created_at >= now() - interval '30 days' group by model order by cost desc
  ),
  agg_day as (
    select to_char(date_trunc('day', created_at), 'YYYY-MM-DD') as d,
           count(*) calls, coalesce(sum(total_tokens),0) tokens, coalesce(sum(estimated_cost_usd),0) cost
    from base where created_at >= now() - interval '30 days'
    group by 1 order by 1
  ),
  agg_user as (
    select b.user_id, coalesce(pr.full_name,'—') full_name,
           count(*) calls, coalesce(sum(b.total_tokens),0) tokens, coalesce(sum(b.estimated_cost_usd),0) cost
    from base b left join public.profiles pr on pr.id = b.user_id
    where b.created_at >= now() - interval '30 days'
    group by b.user_id, pr.full_name order by cost desc limit 20
  )
  select jsonb_build_object(
    'generated_at', now(),
    'totals', (select jsonb_object_agg(label, jsonb_build_object('calls',calls,'tokens',tokens,'cost',cost)) from totals),
    'by_function', coalesce((select jsonb_agg(jsonb_build_object('fn',fn,'calls',calls,'tokens',tokens,'cost',cost)) from agg_fn),'[]'),
    'by_model', coalesce((select jsonb_agg(jsonb_build_object('model',model,'calls',calls,'tokens',tokens,'cost',cost)) from agg_model),'[]'),
    'by_day', coalesce((select jsonb_agg(jsonb_build_object('day',d,'calls',calls,'tokens',tokens,'cost',cost)) from agg_day),'[]'),
    'by_user', coalesce((select jsonb_agg(jsonb_build_object('user_id',user_id,'full_name',full_name,'calls',calls,'tokens',tokens,'cost',cost)) from agg_user),'[]')
  ) into result;
  return result;
end;
$$;

