-- Partage mutuel de fiches (personne/compte) entre membres d'une même
-- organisation : contrairement à handoverPerson/reassignAccounts (transfert
-- EXCLUSIF, l'ancien owner perd la main), un partage est ADDITIF — l'expéditeur
-- garde sa relation, le destinataire en reçoit une vue en plus. Fondation pour
-- la future vue « entreprise » (agrégation multi-expéditeurs) : un partage par
-- ligne, jamais fusionné ici.
create table if not exists public.fiche_shares (
  id uuid primary key default gen_random_uuid(),
  organization_id uuid not null references public.organizations(id) on delete cascade,
  entity_type text not null check (entity_type in ('contact', 'company')),
  entity_id uuid not null,
  from_user_id uuid not null references auth.users(id) on delete cascade,
  to_user_id uuid not null references auth.users(id) on delete cascade,
  note text,
  created_at timestamptz not null default now(),
  unique (organization_id, entity_type, entity_id, from_user_id, to_user_id)
);

comment on table public.fiche_shares is
  'Partage additif d''une fiche (contact/company) entre deux membres de la même organisation. L''expéditeur garde sa relation ; jamais de suppression/écrasement, seulement des lignes de partage cumulées.';

create index if not exists fiche_shares_entity_idx on public.fiche_shares(organization_id, entity_type, entity_id);
create index if not exists fiche_shares_to_user_idx on public.fiche_shares(to_user_id);

alter table public.fiche_shares enable row level security;

drop policy if exists fiche_shares_member_select on public.fiche_shares;
create policy fiche_shares_member_select on public.fiche_shares
for select to authenticated
using (private.is_org_member(organization_id));

grant select on public.fiche_shares to authenticated;

-- Partage une fiche avec un autre membre de l'organisation. Le destinataire
-- doit être membre de la même org (cohérent avec le sélecteur de passation,
-- déjà limité aux membres du workspace). Idempotent : repartager la même
-- fiche au même destinataire met juste à jour la note/date.
create or replace function public.share_fiche(
  p_organization_id uuid,
  p_entity_type text,
  p_entity_id uuid,
  p_to_user_id uuid,
  p_note text default null
)
returns uuid
language plpgsql
security definer
set search_path to 'public', 'private', 'pg_temp'
as $function$
declare
  v_share_id uuid;
begin
  if auth.uid() is null or not private.is_org_member(p_organization_id) then
    raise exception 'Accès refusé à cette organisation';
  end if;

  if p_entity_type not in ('contact', 'company') then
    raise exception 'Type de fiche invalide';
  end if;

  if p_to_user_id = auth.uid() then
    raise exception 'Impossible de se partager une fiche à soi-même';
  end if;

  if not exists (
    select 1 from public.memberships m
    where m.organization_id = p_organization_id and m.user_id = p_to_user_id
  ) then
    raise exception 'Le destinataire doit être membre de l''organisation';
  end if;

  if p_entity_type = 'contact' and not exists (
    select 1 from public.contacts c where c.id = p_entity_id and c.organization_id = p_organization_id
  ) then
    raise exception 'Personne introuvable';
  end if;

  if p_entity_type = 'company' and not exists (
    select 1 from public.companies c where c.id = p_entity_id and c.organization_id = p_organization_id
  ) then
    raise exception 'Compte introuvable';
  end if;

  insert into public.fiche_shares (organization_id, entity_type, entity_id, from_user_id, to_user_id, note)
  values (p_organization_id, p_entity_type, p_entity_id, auth.uid(), p_to_user_id, nullif(trim(p_note), ''))
  on conflict (organization_id, entity_type, entity_id, from_user_id, to_user_id)
  do update set note = excluded.note, created_at = now()
  returning id into v_share_id;

  insert into public.audit_logs (organization_id, actor_user_id, action, target_table, target_id, metadata)
  values (p_organization_id, auth.uid(), 'fiche_shared', 'fiche_shares', v_share_id,
    jsonb_build_object('entity_type', p_entity_type, 'entity_id', p_entity_id, 'to_user_id', p_to_user_id));

  return v_share_id;
end;
$function$;

-- Partages reçus pour une fiche donnée : qui me l'a partagée, et son rôle dans
-- l'organisation (utilisé pour le petit titre Manager/Directeur/Collaborateur).
create or replace function public.list_fiche_shares(
  p_organization_id uuid,
  p_entity_type text,
  p_entity_id uuid
)
returns jsonb
language plpgsql
stable
security definer
set search_path to 'public', 'private', 'auth', 'pg_temp'
as $function$
begin
  if auth.uid() is null or not private.is_org_member(p_organization_id) then
    raise exception 'Accès refusé à cette organisation';
  end if;

  return coalesce((
    select jsonb_agg(jsonb_build_object(
      'id', fs.id,
      'from_user_id', fs.from_user_id,
      'from_name', coalesce(nullif(p.full_name, ''), split_part(u.email, '@', 1)),
      'from_role', m.role,
      'to_user_id', fs.to_user_id,
      'note', fs.note,
      'created_at', fs.created_at
    ) order by fs.created_at desc)
    from public.fiche_shares fs
    join auth.users u on u.id = fs.from_user_id
    left join public.profiles p on p.id = fs.from_user_id
    left join public.memberships m on m.organization_id = fs.organization_id and m.user_id = fs.from_user_id
    where fs.organization_id = p_organization_id
      and fs.entity_type = p_entity_type
      and fs.entity_id = p_entity_id
      and fs.to_user_id = auth.uid()
  ), '[]'::jsonb);
end;
$function$;

-- Retire un partage que J'AI émis (jamais celui d'un tiers) — le destinataire
-- perd la vue « entreprise » issue de ce partage, l'expéditeur garde sa propre
-- relation intacte (le partage n'a jamais touché sa fiche).
create or replace function public.revoke_fiche_share(p_share_id uuid)
returns void
language plpgsql
security definer
set search_path to 'public', 'pg_temp'
as $function$
declare
  v_organization_id uuid;
begin
  select organization_id into v_organization_id
  from public.fiche_shares
  where id = p_share_id and from_user_id = auth.uid();

  if v_organization_id is null then
    raise exception 'Partage introuvable';
  end if;

  delete from public.fiche_shares where id = p_share_id;

  insert into public.audit_logs (organization_id, actor_user_id, action, target_table, target_id, metadata)
  values (v_organization_id, auth.uid(), 'fiche_share_revoked', 'fiche_shares', p_share_id, '{}'::jsonb);
end;
$function$;

-- Bascule contacts : l'appartenance à l'org ne donne plus, à elle seule, accès aux
-- contacts des autres membres. Visible seulement par son owner_user_id, ou par un
-- destinataire explicite d'un partage fiche_shares. L'écriture reste réservée au
-- owner. (Rollback : recréer contacts_member_all avec is_org_member et dropper les
-- deux policies ci-dessous.)
drop policy if exists contacts_member_all on public.contacts;

create policy contacts_owner_write on public.contacts
  for all
  using (owner_user_id = auth.uid() and private.is_org_member(organization_id))
  with check (owner_user_id = auth.uid() and private.is_org_member(organization_id));

create policy contacts_shared_select on public.contacts
  for select
  using (
    private.is_org_member(organization_id)
    and exists (
      select 1 from public.fiche_shares fs
      where fs.entity_type = 'contact' and fs.entity_id = contacts.id and fs.to_user_id = auth.uid()
    )
  );

-- Étend la bascule "privé par défaut + partage explicite" à toutes les tables
-- satellites de la fiche personne (celles interrogées par getPersonDetail). Même
-- remplacement mécanique partout : private.is_org_member(organization_id) devient
-- private.can_view_contact(organization_id, contact_id) (ou équivalent quand la
-- colonne de référence diffère). Les comptes/entreprises ne sont pas touchés ici
-- (Phase 2, plus tard).

-- behavioral_signals
drop policy if exists behavioral_signals_member_all on public.behavioral_signals;
create policy behavioral_signals_can_view on public.behavioral_signals
  for all
  using (private.can_view_contact(organization_id, contact_id))
  with check (private.can_view_contact(organization_id, contact_id));

-- cognitive_profiles
drop policy if exists cognitive_profiles_member_all on public.cognitive_profiles;
create policy cognitive_profiles_can_view on public.cognitive_profiles
  for all
