-- Retourne le détail des invitations acceptées (nom d'organisation + nom de
-- l'invitant) pour que le frontend puisse afficher « Tu es maintenant membre
-- de l'équipe de X » après un clic sur le lien d'invitation. Corrige au passage
-- le même bug de sentinel « illimité » (max_licenses = -1) déjà traité dans
-- invite-team-member : greatest(-1,1)=1 plafonnait à 1 siège les plans illimités.
drop function if exists public.accept_my_organization_invitations();

create or replace function public.accept_my_organization_invitations()
returns table(organization_name text, inviter_name text)
language plpgsql
security definer
set search_path to 'public', 'auth', 'pg_temp'
as $$
declare
  v_email text;
  v_invitation public.organization_invitations%rowtype;
  v_subscription public.subscriptions%rowtype;
  v_plan_limit integer;
  v_member_count integer;
  v_unlimited boolean;
  v_org_name text;
  v_inviter_name text;
begin
  select lower(email) into v_email from auth.users where id = auth.uid();
  if v_email is null then return; end if;

  for v_invitation in
    select * from public.organization_invitations
    where email = v_email and status = 'pending' and expires_at > now()
    order by created_at
  loop
    select * into v_subscription from public.subscriptions
    where organization_id = v_invitation.organization_id
    order by created_at desc limit 1;
    select max_licenses into v_plan_limit
    from public.subscription_plans
    where id = coalesce(v_subscription.plan_id, 'free');
    select count(*) into v_member_count from public.memberships
    where organization_id = v_invitation.organization_id;
    v_unlimited := coalesce(v_plan_limit, 1) < 0;

    if v_unlimited or v_member_count < least(
      greatest(coalesce(v_subscription.seat_quantity, 1), 1),
      greatest(coalesce(v_plan_limit, 1), 1)
    ) then
      insert into public.memberships (organization_id, user_id, role)
      values (v_invitation.organization_id, auth.uid(), v_invitation.role)
      on conflict (organization_id, user_id) do update set role = excluded.role;

      update public.organization_invitations
      set status = 'accepted', accepted_at = now(), updated_at = now()
      where id = v_invitation.id;

      insert into public.audit_logs (
        organization_id, actor_user_id, action, target_table, target_id, metadata
      ) values (
        v_invitation.organization_id, auth.uid(), 'team_invitation_accepted',
        'memberships', auth.uid(), jsonb_build_object('email', v_email, 'role', v_invitation.role)
      );

      select o.name into v_org_name from public.organizations o where o.id = v_invitation.organization_id;
      select p.full_name into v_inviter_name from public.profiles p where p.id = v_invitation.invited_by;
      organization_name := coalesce(v_org_name, 'l’équipe');
      inviter_name := v_inviter_name;
      return next;
    end if;
  end loop;
end;
$$;

grant execute on function public.accept_my_organization_invitations() to authenticated;

-- La passation (réattribution de contacts) est cassée par les RLS "fiches
-- privées par défaut" (contacts_owner_write exige owner_user_id = auth.uid()
-- en USING ET en WITH CHECK, donc personne — même le owner actuel — ne peut
-- jamais changer owner_user_id vers quelqu'un d'autre). RPC security definer
-- dédiée : ouverte à tout membre de l'org (comportement d'avant l'ajout du
-- partage de fiches), transfert + journal contact_transfers atomiques.
create or replace function public.transfer_contact_ownership(
  p_organization_id uuid,
  p_contact_ids uuid[],
  p_to_user_id uuid
)
returns integer
language plpgsql
security definer
set search_path = public
as $$
declare
  v_transferred integer;
begin
  if not private.is_org_member(p_organization_id) then
    raise exception 'Not authorized';
  end if;
  if not exists (
    select 1 from public.memberships
    where organization_id = p_organization_id and user_id = p_to_user_id
  ) then
    raise exception 'Target user is not a member of this organization';
  end if;

  with targets as (
    select id, owner_user_id as from_user_id
    from public.contacts
    where organization_id = p_organization_id
      and id = any(p_contact_ids)
      and merged_into_contact_id is null
      and owner_user_id is distinct from p_to_user_id
  ),
  updated as (
    update public.contacts c
    set owner_user_id = p_to_user_id
    from targets t
    where c.id = t.id
    returning c.id
  ),
  logged as (
    insert into public.contact_transfers (organization_id, contact_id, from_user_id, to_user_id, kept_copy, transferred_by)
    select p_organization_id, t.id, t.from_user_id, p_to_user_id, false, auth.uid()
    from targets t
    returning 1
  )
  select count(*) into v_transferred from targets;

  return v_transferred;
end;
$$;

revoke all on function public.transfer_contact_ownership(uuid, uuid[], uuid) from public, anon;
grant execute on function public.transfer_contact_ownership(uuid, uuid[], uuid) to authenticated;

